add('ovo','OVO-Bench','CVPR 2025','Current state / past evidence / future response','Real-time perception, backward tracing and forward active responding.','Test context retention, current versus last-seen state and causal delivery.','Official per-task / per-mode scores','644 videos · 3,100 queries','https://huggingface.co/datasets/JoeLeelyf/OVO-Bench','https://github.com/JoeLeelyf/OVO-Bench','Use ~44 GB source archive plus official chunker, or ~144 GB pre-chunked archives; pin release.','Published and revised code protocols differ. CC BY-NC-SA and source licenses apply. No verified score imported in this catalog.',1)
add('streamingbench','StreamingBench','Public benchmark','General perception / audio / contextual QA','18 tasks with questions at multiple video timestamps.','Check that cheaper context does not degrade general understanding.','Overall accuracy','900 videos · 4,500 QA on project page','https://huggingface.co/datasets/mjuicem/StreamingBench',stream,'Download official videos and QA on GCP; reconcile actual revision counts before freezing.','Posted results mostly use older model versions and different frame budgets; not a current universal SOTA.',2,[result('Gemini 1.5 Pro',70.26,'Overall accuracy','Official site historical overall table; video input.',stream),result('MiniCPM-o 2.6',66.01,'Overall accuracy','Official site historical overall table; 60 frames.',stream)])
add('omnipro','OmniPro','Preprint · 2026','Audio-visual events / proactive interaction','Probe tests pre/post event understanding; Online tests timing and content jointly.','Compare audio-only, vision-only and fused context; retain non-speech evidence.','Probe paired accuracy / Online F1','2,700 samples · 9 tasks','https://huggingface.co/datasets/RuixiangZhao/OmniPro','https://github.com/RuixiangZhao/OmniPro','Keep raw video/audio and trigger labels; implement a persistent begin/observe/end adapter.','84% audio dependency. Probe and Online are distinct leaderboards. Preserve official matching tolerance and judge.',2,[result('Gemini-3-Flash',40.4,'Probe paired accuracy','Paper Table 2; prompted pre/post evaluation, not Online.',omni),result('MiniCPM-o 4.5',20.9,'Online F1','Paper Table 2; 1 FPS and ±3s matching.',omni)])
